package com.codepilot1c.core.tools.development;
import java.util.concurrent.CompletableFuture;import com.google.gson.Gson;import com.codepilot1c.core.tools.*;import com.codepilot1c.core.edt.development.*;
@ToolMeta(name="edt_data_assert",category="qa",mutating=true,tags={"workspace","edt","sensitive"})
public final class EdtDataAssertTool extends AbstractTool {
 public String getDescription(){return "Batch 1..32 read queries through an already running owned native host for the project's current base. Typed scalar_equals or row_count_equals; one native request, status returns only passed ids and failed actual/expected values. JSON scalar parameters only; scalar query must return exactly one row/column. 1000-row bound, truncation never passes. No data creation or client launch. Durable key never automatically resends unknown outcomes. Use fresh keys after data changes; original native host/query commands remain available.";}
 public String getParameterSchema(){return """
 {"type":"object","additionalProperties":false,"required":["action"],"properties":{"action":{"enum":["start","status"]},"project":{"type":"string"},"host_id":{"type":"string"},"idempotency_key":{"type":"string"},"assertion_id":{"type":"string"},"checks":{"type":"array","minItems":1,"maxItems":32,"items":{"type":"object","additionalProperties":false,"required":["id","query","kind","expected"],"properties":{"id":{"type":"string"},"query":{"type":"string"},"parameters":{"type":"object"},"kind":{"enum":["scalar_equals","row_count_equals"]},"expected":{}}}}}}
 """;}
 protected CompletableFuture<ToolResult> doExecute(ToolParameters p){return CompletableFuture.supplyAsync(()->{try{var s=DataAssertionService.workspace();Object out=switch(p.requireString("action")){case "start"->s.start(p.requireString("project"),p.requireString("host_id"),p.requireString("idempotency_key"),p.getRaw().get("checks"));case "status"->s.status(p.requireString("assertion_id"));default->throw new IllegalArgumentException("Unknown action");};return ToolResult.success(new com.google.gson.GsonBuilder().serializeNulls().create().toJson(out));}catch(Exception e){return ToolResult.failure("edt_data_assert: "+e.getMessage());}});}
}
